// File: export.service.ts
// Path: src/services/ai/export.service.ts
//
// Canvas exports (spec §8), built server-side from the VALIDATED spec with fresh,
// scope-enforced data — never from what the browser sends back.
//   Excel (exceljs):    Summary sheet (KPIs) + one sheet per block
//   PPT   (pptxgenjs):  title slide + one slide per block (native, editable charts)
//   PDF:  printed by the browser from the rendered canvas (see aiCanvas.controller)
// Every file carries "Generated by <user> on <date time> · SFJBS CRM".
// Money is full rupees with Indian grouping (₹1,00,000) — never K / L / Cr.

import ExcelJS from "exceljs";
import PptxGenJS from "pptxgenjs";
import type { AuthUser } from "@/types/express";
import type { RenderedBlock } from "@/services/ai/canvas.service";
import type { Column, QueryResult, ValueFormat } from "@/config/queryRegistry";

const inr = new Intl.NumberFormat("en-IN", { maximumFractionDigits: 2 });
const fmt = (v: number | null | undefined, f: ValueFormat | Column["type"]) => {
  if (v === null || v === undefined || Number.isNaN(v)) return "—";
  if (f === "money") return `₹${inr.format(v)}`;
  if (f === "percent") return `${inr.format(v)}%`;
  return inr.format(v);
};
// Excel has no Indian-grouping code; this conditional format gives ₹1,00,00,000.00
const INR_FMT = '[>=10000000]"₹"##\\,##\\,##\\,##0.00;[>=100000]"₹"##\\,##\\,##0.00;"₹"##,##0.00';

export const generatedBy = (user: AuthUser, now = new Date()) =>
  `Generated by ${`${user.firstName} ${user.lastName}`.trim()} on ${now.toLocaleString("en-IN", {
    timeZone: "Asia/Kolkata",
    day: "2-digit",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  })} · SFJBS CRM`;

const safeSheet = (name: string, used: Set<string>) => {
  let base = name.replace(/[\\/?*[\]:]/g, " ").slice(0, 28).trim() || "Sheet";
  let n = base;
  for (let i = 2; used.has(n.toLowerCase()); i++) n = `${base.slice(0, 25)} ${i}`;
  used.add(n.toLowerCase());
  return n;
};

/** a block's data as header + rows (series and rows both become a table) */
const tabular = (r: QueryResult): { columns: Column[]; rows: Record<string, unknown>[] } | null => {
  if (r.kind === "rows") return { columns: r.columns, rows: r.rows };
  if (r.kind === "tree") {
    // the org chart as a list, top down
    const rows: Record<string, unknown>[] = [];
    const byId = new Map<string, string>();
    const walk = (n: (typeof r)["root"], boss: string | null) => {
      const name = `${n.firstName} ${n.lastName ?? ""}`.trim();
      byId.set(n.id, name);
      if (!n.virtual) rows.push({ name, role: n.role.name, reportsTo: boss, teamSize: n.teamSize, clients: n.stats.clients, spocs: n.stats.spocs, openTasks: n.stats.openTasks, overdue: n.stats.overdue });
      n.children.forEach((c) => walk(c, n.virtual ? null : name));
    };
    walk(r.root, null);
    return {
      columns: [
        { key: "name", label: "Person", type: "text" },
        { key: "role", label: "Role", type: "text" },
        { key: "reportsTo", label: "Reports to", type: "text" },
        { key: "teamSize", label: "People below", type: "number" },
        { key: "clients", label: "Clients", type: "number" },
        { key: "spocs", label: "SPOCs", type: "number" },
        { key: "openTasks", label: "Open tasks", type: "number" },
        { key: "overdue", label: "Overdue", type: "number" },
      ],
      rows,
    };
  }
  if (r.kind === "series") {
    const t = r.format === "money" ? "money" : r.format === "percent" ? "percent" : "number";
    return {
      columns: [{ key: "label", label: "", type: "text" }, ...r.series.map((s) => ({ key: s.key, label: s.label, type: t as Column["type"] }))],
      rows: r.points,
    };
  }
  return null;
};

export const toExcel = async (title: string, blocks: RenderedBlock[], user: AuthUser): Promise<Buffer> => {
  const wb = new ExcelJS.Workbook();
  wb.creator = "SFJBS CRM";
  wb.created = new Date();
  const footer = generatedBy(user);
  const used = new Set<string>();

  const summary = wb.addWorksheet(safeSheet("Summary", used));
  summary.addRow([title]).font = { bold: true, size: 14 };
  summary.addRow([footer]).font = { italic: true, color: { argb: "FF64748B" } };
  summary.addRow([]);
  const kpis = blocks.filter((b) => b.result?.kind === "single");
  if (kpis.length) {
    summary.addRow(["Measure", "Value", "Note"]).font = { bold: true };
    for (const b of kpis) {
      const r = b.result as Extract<QueryResult, { kind: "single" }>;
      const row = summary.addRow([b.title, r.value, r.hint ?? ""]);
      if (r.format === "money") row.getCell(2).numFmt = INR_FMT;
      if (r.format === "percent") row.getCell(2).numFmt = '0.0"%"';
    }
  }
  summary.getColumn(1).width = 36;
  summary.getColumn(2).width = 24;
  summary.getColumn(3).width = 24;

  for (const b of blocks) {
    if (!b.result || b.result.kind === "single") continue;
    const t = tabular(b.result);
    if (!t) continue;
    const ws = wb.addWorksheet(safeSheet(b.title, used));
    ws.addRow([b.title]).font = { bold: true, size: 13 };
    ws.addRow([]);
    const head = ws.addRow(t.columns.map((c) => c.label || "Label"));
    head.font = { bold: true, color: { argb: "FFFFFFFF" } };
    head.eachCell((c) => (c.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FF4F46E5" } }));
    for (const r of t.rows) {
      const row = ws.addRow(t.columns.map((c) => r[c.key] ?? null));
      t.columns.forEach((c, i) => {
        if (c.type === "money") row.getCell(i + 1).numFmt = INR_FMT;
      });
    }
    if (b.result.kind === "rows" && b.result.total > t.rows.length) {
      ws.addRow([`Showing ${inr.format(t.rows.length)} of ${inr.format(b.result.total)} rows (export limit).`]).font = { italic: true };
    }
    ws.addRow([]);
    ws.addRow([footer]).font = { italic: true, color: { argb: "FF64748B" } };
    t.columns.forEach((c, i) => (ws.getColumn(i + 1).width = c.type === "text" ? 32 : 20));
    ws.views = [{ state: "frozen", ySplit: 3 }];
    ws.headerFooter = { oddFooter: footer };
  }
  summary.headerFooter = { oddFooter: footer };
  return Buffer.from(await wb.xlsx.writeBuffer());
};

const PPT_ROWS_PER_SLIDE = 14;
const PPT_MAX_TABLE_ROWS = 140;

export const toPptx = async (title: string, blocks: RenderedBlock[], user: AuthUser): Promise<Buffer> => {
  const pptx = new PptxGenJS();
  pptx.layout = "LAYOUT_WIDE";
  pptx.title = title;
  const footer = generatedBy(user);
  const addFooter = (s: PptxGenJS.Slide) => s.addText(footer, { x: 0.4, y: 7.05, w: 12.5, h: 0.3, fontSize: 9, color: "64748B", italic: true });

  const first = pptx.addSlide();
  first.background = { color: "EEF2FF" };
  first.addText(title, { x: 0.6, y: 2.4, w: 12, h: 1.2, fontSize: 36, bold: true, color: "1E1B4B" });
  first.addText(footer, { x: 0.6, y: 3.8, w: 12, h: 0.5, fontSize: 14, color: "475569" });

  for (const b of blocks) {
    if (!b.result) continue;
    const r = b.result;
    if (r.kind === "single") {
      const s = pptx.addSlide();
      s.addText(b.title, { x: 0.6, y: 0.5, w: 12, h: 0.7, fontSize: 24, bold: true, color: "1E1B4B" });
      s.addText(fmt(r.value, r.format), { x: 0.6, y: 2.4, w: 12, h: 1.6, fontSize: 60, bold: true, color: "4F46E5", align: "center" });
      if (r.hint) s.addText(r.hint, { x: 0.6, y: 4.1, w: 12, h: 0.5, fontSize: 16, color: "64748B", align: "center" });
      addFooter(s);
      continue;
    }
    if (r.kind === "series" && b.component !== "table") {
      const s = pptx.addSlide();
      s.addText(b.title, { x: 0.6, y: 0.4, w: 12, h: 0.6, fontSize: 22, bold: true, color: "1E1B4B" });
      const labels = r.points.map((p) => String(p.label));
      const data = r.series.map((ser) => ({ name: ser.label, labels, values: r.points.map((p) => Number(p[ser.key] ?? 0)) }));
      const type = b.component === "line" ? pptx.ChartType.line : b.component === "pie" ? pptx.ChartType.pie : pptx.ChartType.bar;
      s.addChart(type, b.component === "pie" ? data.slice(0, 1) : data, {
        x: 0.6,
        y: 1.2,
        w: 12.1,
        h: 5.6,
        showLegend: data.length > 1 || b.component === "pie",
        legendPos: "b",
        ...(b.component === "pie" ? { showPercent: true } : { valAxisLabelFormatCode: r.format === "money" ? "₹#,##0" : "#,##0" }),
      });
      addFooter(s);
      continue;
    }
    const t = tabular(r);
    if (!t) continue;
    const rows = t.rows.slice(0, PPT_MAX_TABLE_ROWS);
    for (let i = 0; i < Math.max(rows.length, 1); i += PPT_ROWS_PER_SLIDE) {
      const s = pptx.addSlide();
      s.addText(i ? `${b.title} (continued)` : b.title, { x: 0.6, y: 0.4, w: 12, h: 0.6, fontSize: 22, bold: true, color: "1E1B4B" });
      const head = t.columns.map((c) => ({ text: c.label || "", options: { bold: true, color: "FFFFFF", fill: { color: "4F46E5" } } }));
      const body = rows.slice(i, i + PPT_ROWS_PER_SLIDE).map((row) =>
        t.columns.map((c) => {
          const v = row[c.key];
          return { text: typeof v === "number" ? fmt(v, c.type) : v === null || v === undefined ? "" : String(v) };
        }),
      );
      s.addTable([head, ...body], { x: 0.6, y: 1.2, w: 12.1, fontSize: 11, border: { type: "solid", color: "E2E8F0", pt: 0.5 }, autoPage: false });
      addFooter(s);
    }
  }
  return (await pptx.write({ outputType: "nodebuffer" })) as Buffer;
};
